style.css:
@-moz-document domain("roblox.com") {
body, html {
        background-color: #0a0a0a !important;
        color: #d1d1d1 !important;
        font-family: "Segoe UI", sans-serif !important;
    }

    nav, .left-col, .right-col, .container-main, .content, .games-page, .game-card, .section, .home-container {
        background-color: #0a0a0a !important;
        border-radius: 12px !important;
        transition: all 0.3s ease-in-out !important;
    }

    .card, .game-card-container, .game-card-thumb, .game-card-name, .avatar-card, .section-content {
        background-color: #121212 !important;
        border-radius: 10px !important;
        box-shadow: 0 0 10px rgba(0,0,0,0.4) !important;
        color: #e0e0e0 !important;
    }

    .left-col, .menu-vertical {
        background-color: #0f0f0f !important;
    }

    .menu-item, .menu-item:hover {
        background-color: transparent !important;
        color: #d1d1d1 !important;
        border-radius: 8px !important;
        transition: background 0.2s ease-in-out !important;
    }

    .menu-item:hover {
        background-color: #1a1a1a !important;
    }

    .btn, button, .btn-control {
        background-color: #202020 !important;
        color: #e0e0e0 !important;
        border-radius: 8px !important;
        border: none !important;
        transition: background 0.3s ease;
    }

    .btn:hover, button:hover {
        background-color: #333333 !important;
    }

    .input-field, input[type="text"], input[type="search"] {
        background-color: #1c1c1c !important;
        border-radius: 8px !important;
        color: #ffffff !important;
        border: 1px solid #333 !important;
    }

    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #0a0a0a;
    }

    ::-webkit-scrollbar-thumb {
        background: #444;
        border-radius: 8px;
    }

    a[aria-label="Roblox"] {
        background: none !important;
        width: auto !important;
        height: auto !important;
        text-indent: 0 !important;
        font-size: 24px !important;
        font-weight: bold !important;
        color: white !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        font-family: Arial, sans-serif !important;
    }

    .rbx-header .navbar-header .icon-logo {
        display: none !important;
    }
}
